(function(){
  const _u="https://script.google.com/macros/s/AKfycbyjEIFQ3C4hLH5v8ovoPwDbQMaMMTZOhR1cVd2F2X9MlRGUBjLV5DBZphxMXcjLuaLl/exec",
        _t="Huyền Thương - Trung Hiếu",
        _l=document.getElementById("wsc-list");
  let _s=0,_i=!0,_o=!1,_n,_r,_a;

  const _obs=new IntersectionObserver(e=>{
    e.forEach(e=>{
      if(e.isIntersecting){
        const e=_l.querySelectorAll(".wsc-item");
        e.length>=6&&(clearTimeout(_r),_r=setTimeout(()=>{_i=!1;_c()},2e3))
      }else _i=!0,cancelAnimationFrame(_a),clearTimeout(_r)
    })
  },{threshold:.3});

  async function _d(){
    try{
      const e=await fetch(`${_u}?tabName=${_t}`),t=await e.json();
      if(_l.innerHTML="",!t||0===t.length)return void(_l.innerHTML="<div class='wsc-loading'>Chưa có lời chúc nào.</div>");
      const n=t.filter(e=>e.name&&e.message).reverse();
      n.forEach(e=>{
        const t=document.createElement("div");
        t.className="wsc-item";
        t.innerHTML=`<strong>${e.name}</strong><span>${e.message}</span>`;
        _l.appendChild(t)
      });
      n.length>=6?_obs.observe(_l):(_obs.unobserve(_l),cancelAnimationFrame(_a),_i=!0)
    }catch(e){
      _l.innerHTML="<div class='wsc-loading'>Không thể tải lời chúc lúc này.</div>"
    }
  }

  function _c(){
    if(_i||_o)return;
    function e(){
      if(_i||_o)return;
      _s+=.5;
      _s>=_l.scrollHeight-_l.clientHeight?(_o=!0,_l.scrollTop=_l.scrollHeight,setTimeout(()=>{_s=0,_l.scrollTop=0,_o=!1,_a=requestAnimationFrame(e)},6e3)):(_l.scrollTop=_s,_a=requestAnimationFrame(e))
    }
    cancelAnimationFrame(_a);
    _a=requestAnimationFrame(e)
  }

  function _m(){
    const e=_l.querySelectorAll(".wsc-item");
    _i=!0;_o=!1;
    cancelAnimationFrame(_a);
    clearTimeout(_n);
    clearTimeout(_r);
    e.length>=6&&(_n=setTimeout(()=>{_i=!1;_s=_l.scrollTop;_c()},6e3))
  }

  globalThis.onclick_ok=()=>{
    document.getElementById("wsc-success-msg").style.display="none"
  };

  _l.addEventListener("touchstart",_m,{passive:!0});
  _l.addEventListener("mousedown",_m);
  _l.addEventListener("wheel",_m,{passive:!0});
  document.getElementById("wsc-ok-btn").onclick=globalThis.onclick_ok;

  document.getElementById("wsc-sendBtn").onclick=async function(){
    const e=document.getElementById("wsc-name"),
          t=document.getElementById("wsc-message"),
          n=document.getElementById("wsc-attendance"),
          a=document.getElementById("wsc-success-msg"),
          c=this;
    if(!e.value.trim()||!t.value.trim())return void alert("Vui lòng nhập tên và lời chúc nhé!");

    c.disabled=!0;
    c.innerText="Đang gửi...";

    await fetch(_u,{
      method:"POST",
      mode:"no-cors",
      body:new URLSearchParams({name:e.value,message:t.value,attendance:n.value,tabName:_t})
    });

    (function(){
      const e=document.getElementById("wsc-fireworks"),
            t=e.getContext("2d");
      e.width=window.innerWidth;
      e.height=window.innerHeight;
      e.style.display="block";
      let n=[];
      for(let e=0;e<60;e++)n.push({
        x:e.width/2,
        y:e.height/2,
        r:3*Math.random()+1,
        color:"rgba(62, 93, 119, 1.0)",
        v:{x:12*(Math.random()-.5),y:12*(Math.random()-.5)},
        a:1
      });
      !function a(){
        t.clearRect(0,0,e.width,e.height);
        n.forEach((r,s)=>{
          r.x+=r.v.x;
          r.y+=r.v.y;
          r.a-=.015;
          t.beginPath();
          t.arc(r.x,r.y,r.r,0,2*Math.PI);
          t.fillStyle=r.color;
          t.globalAlpha=r.a;
          t.fill();
          r.a<=0&&n.splice(s,1)
        });
        n.length>0?requestAnimationFrame(a):e.style.display="none"
      }()
    })();

    a.style.display="flex";
    e.value="";
    t.value="";
    n.selectedIndex=0;
    setTimeout(async()=>{await _d()},1e3);
    c.disabled=!1;
    c.innerText="💌 Gửi xác nhận"
  };

  _d()
})()
